INSERT INTO upload_approval_audit (
      upload_id
    , source_id
    , action
    , action_by
    , action_date
    , action_time
    , previous_status
    , new_status
    , reason
    , created_at
) VALUES (
      #{uploadId}
    , #{sourceId}
    , #{action}
    , #{actionBy}
    , #{firstRegisterDate}
    , #{firstRegisterTime}
    , #{previousStatus}
    , #{newStatus}
    , #{reason}
    , NOW()
)
